package dev.rodrigo.locationlab; import android.content.*; import android.util.Log; import com.google.android.gms.location.*; public class ActivityReceiver extends BroadcastReceiver { public void onReceive(Context c,Intent i){if(!ActivityRecognitionResult.hasResult(i))return;ActivityRecognitionResult r=ActivityRecognitionResult.extractResult(i);if(r!=null){DetectedActivity a=r.getMostProbableActivity();Log.i("ActivityLab","type="+a.getType()+" confidence="+a.getConfidence());}} }